#[derive(Debug, Serialize)]
struct ApiResponse<T> {
    ok: bool,
    data: T,
}

fn json_api_response<T: Serialize>(ok: bool, data: T) -> Json<Value> {
    let mut value = json!({
        "ok": ok,
        "data": data,
    });
    normalize_json_strings(&mut value);
    Json(value)
}

