async fn api_send_message_stream(
    State(state): State<WebAppState>,
    Json(payload): Json<SendMessageRequest>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    let session_id = ensure_current_session(&state).map_err(internal_error)?;
    let turn_model = lock_runtime_settings(&state)
        .map_err(internal_error)?
        .model
        .clone();
    let runtime_model = turn_model.clone();
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<StreamEnvelope>();
    let state_for_task = state.clone();
    let content = payload.content;
    let mode = payload.mode;
    let language = payload.language;
    let attachments = payload.attachments;
    let recovery_user_content = content.clone();
    let recovery_mode = mode.clone();
    let recovery_language = language.clone();
    let session_id_for_task = session_id.clone();
    let tx_for_runtime = tx.clone();
    let state_for_cleanup = state_for_task.clone();
    let (runtime_ready_tx, runtime_ready_rx) = oneshot::channel::<()>();
    let handle = Arc::new(tokio::spawn(async move {
        if runtime_ready_rx.await.is_err() {
            return;
        }
        let result = AssertUnwindSafe(run_chat_request_stream(
            state_for_task,
            session_id_for_task.clone(),
            content,
            mode,
            language,
            attachments,
            turn_model,
            tx.clone(),
        ))
        .catch_unwind()
        .await;

        match result {
            Ok(Ok(())) => {}
            Ok(Err(err)) => {
                if let Ok((runtime, persisted_blocks)) =
                    recover_stream_finalize_context(&state_for_cleanup, &session_id_for_task)
                {
                    if let Some(plan) = recover_plan_for_finalize(
                        &state_for_cleanup,
                        &runtime,
                        &persisted_blocks,
                        &recovery_user_content,
                        recovery_mode.as_deref(),
                        turn_language_from_option(recovery_language.as_deref()),
                    ) {
                        let required_path_snapshots = load_stream_required_path_snapshots(
                            &state_for_cleanup,
                            &session_id_for_task,
                        );
                        if let Some((report, checkpoints, branch_notes)) =
                            can_finalize_from_hard_verifier_only(
                                &plan,
                                &persisted_blocks,
                                state_for_cleanup.host.base_dir(),
                                &runtime,
                                &required_path_snapshots,
                                turn_language_from_option(recovery_language.as_deref()),
                            )
                        {
                            emit_verifier_update(
                                &tx,
                                &state_for_cleanup,
                                &session_id_for_task,
                                &runtime,
                                &persisted_blocks,
                                recovery_mode.as_deref(),
                                &report,
                                &checkpoints,
                                &branch_notes,
                                turn_language_from_option(recovery_language.as_deref()),
                            );
                            let mut finalized_blocks = persisted_blocks.clone();
                            finalized_blocks.push(MessageBlock::Verification { report });
                            let _ = finalize_stream_success(
                                &tx,
                                &state_for_cleanup,
                                &session_id_for_task,
                                &runtime,
                                &finalized_blocks,
                                recovery_mode.as_deref(),
                                turn_language_from_option(recovery_language.as_deref()),
                                &localized_text(
                                    turn_language_from_option(recovery_language.as_deref()),
                                    "本轮 Agent 已在确定性恢复后完成",
                                    "Agent turn finished after deterministic recovery",
                                ),
                            );
                            return;
                        }
                    }
                }
                finalize_stream_failure(
                    &tx,
                    &state_for_cleanup,
                    &session_id_for_task,
                    turn_language_from_option(recovery_language.as_deref()),
                    &err.to_string(),
                );
            }
            Err(payload) => {
                if let Ok((runtime, persisted_blocks)) =
                    recover_stream_finalize_context(&state_for_cleanup, &session_id_for_task)
                {
                    if let Some(plan) = recover_plan_for_finalize(
                        &state_for_cleanup,
                        &runtime,
                        &persisted_blocks,
                        &recovery_user_content,
                        recovery_mode.as_deref(),
                        turn_language_from_option(recovery_language.as_deref()),
                    ) {
                        let required_path_snapshots = load_stream_required_path_snapshots(
                            &state_for_cleanup,
                            &session_id_for_task,
                        );
                        if let Some((report, checkpoints, branch_notes)) =
                            can_finalize_from_hard_verifier_only(
                                &plan,
                                &persisted_blocks,
                                state_for_cleanup.host.base_dir(),
                                &runtime,
                                &required_path_snapshots,
                                turn_language_from_option(recovery_language.as_deref()),
                            )
                        {
                            emit_verifier_update(
                                &tx,
                                &state_for_cleanup,
                                &session_id_for_task,
                                &runtime,
                                &persisted_blocks,
                                recovery_mode.as_deref(),
                                &report,
                                &checkpoints,
                                &branch_notes,
                                turn_language_from_option(recovery_language.as_deref()),
                            );
                            let mut finalized_blocks = persisted_blocks.clone();
                            finalized_blocks.push(MessageBlock::Verification { report });
                            let _ = finalize_stream_success(
                                &tx,
                                &state_for_cleanup,
                                &session_id_for_task,
                                &runtime,
                                &finalized_blocks,
                                recovery_mode.as_deref(),
                                turn_language_from_option(recovery_language.as_deref()),
                                &localized_text(
                                    turn_language_from_option(recovery_language.as_deref()),
                                    "本轮 Agent 已在确定性恢复后完成",
                                    "Agent turn finished after deterministic recovery",
                                ),
                            );
                            return;
                        }
                    }
                }
                finalize_stream_failure(
                    &tx,
                    &state_for_cleanup,
                    &session_id_for_task,
                    turn_language_from_option(recovery_language.as_deref()),
                    &format!("stream task panicked: {}", panic_payload_to_string(payload)),
                );
            }
        }
    }));

    {
        let mut runtime = lock_stream_runtime(&state).map_err(internal_error)?;
        runtime.insert(
            session_id.clone(),
            StreamSessionRuntime {
                task_handle: handle.clone(),
                event_tx: tx_for_runtime,
                pending_approvals: HashMap::new(),
                latest_activity: None,
                tool_events: Vec::new(),
                edited_files: Vec::new(),
                message_blocks: Vec::new(),
                partial_text: String::new(),
                partial_thinking: String::new(),
                context_used_tokens: 0,
                context_window: 0,
                context_usage_estimated: true,
                context_model: runtime_model,
                progress_updates: Vec::new(),
                recent_progress_keys: Vec::new(),
                recent_progress_emitted_at: HashMap::new(),
                required_path_snapshots: Vec::new(),
                subagents: Vec::new(),
                verifier: None,
                checkpoints: Vec::new(),
                branch_notes: Vec::new(),
                timeline: Vec::new(),
                auto_skills: Vec::new(),
            },
        );
    }
    let _ = runtime_ready_tx.send(());

    let stream = async_stream::stream! {
        while let Some(event) = rx.recv().await {
            yield Ok::<Bytes, Infallible>(event_bytes(event));
        }
    };

    Ok((
        [
            (header::CONTENT_TYPE, "application/x-ndjson; charset=utf-8"),
            (header::CACHE_CONTROL, "no-cache"),
            (
                header::HeaderName::from_static("x-content-type-options"),
                "nosniff",
            ),
            (header::HeaderName::from_static("x-accel-buffering"), "no"),
        ],
        Body::from_stream(stream),
    ))
}

