fn to_web_subagent(record: &AgentSubagentRecord) -> WebSubagentEvent {
    let running = record.status.eq_ignore_ascii_case("running");
    let failed = record.status.eq_ignore_ascii_case("failed")
        || record.status.eq_ignore_ascii_case("repair");
    let mut events = vec![WebSubagentOperation {
        kind: "thinking".to_string(),
        label: "Analyzing".to_string(),
        detail: record.purpose.clone(),
        status: if running { "running" } else { "complete" }.to_string(),
        timestamp: record.started_at.clone().unwrap_or_else(web_now_iso),
    }];
    if !record.evidence.is_empty() {
        events.push(WebSubagentOperation {
            kind: "check".to_string(),
            label: "Evidence check".to_string(),
            detail: record
                .evidence
                .iter()
                .take(3)
                .cloned()
                .collect::<Vec<_>>()
                .join(" | "),
            status: if failed { "failed" } else { "complete" }.to_string(),
            timestamp: record.completed_at.clone().unwrap_or_else(web_now_iso),
        });
    }
    if !record.output.trim().is_empty() {
        events.push(WebSubagentOperation {
            kind: "result".to_string(),
            label: "Result".to_string(),
            detail: tail_string(&record.output, 240),
            status: if failed { "failed" } else { "complete" }.to_string(),
            timestamp: record.completed_at.clone().unwrap_or_else(web_now_iso),
        });
    }
    WebSubagentEvent {
        id: record.id.clone(),
        name: record.name.clone(),
        purpose: record.purpose.clone(),
        input: record.input.clone(),
        output: record.output.clone(),
        status: record.status.clone(),
        kind: record.kind.clone(),
        started_at: record.started_at.clone(),
        completed_at: record.completed_at.clone(),
        evidence: record.evidence.clone(),
        events,
    }
}

fn to_web_verifier_check(check: &AgentVerifierCheck) -> WebVerifierCheck {
    WebVerifierCheck {
        id: check.id.clone(),
        title: check.title.clone(),
        status: check.status.clone(),
        detail: check.detail.clone(),
        evidence: check.evidence.clone(),
    }
}

fn to_web_verifier(report: &AgentVerifierReport) -> WebVerifierReport {
    WebVerifierReport {
        status: report.status.clone(),
        summary: report.summary.clone(),
        checks: report.checks.iter().map(to_web_verifier_check).collect(),
        issues: report.issues.clone(),
        evidence: report.evidence.clone(),
        next_actions: report.next_actions.clone(),
        deterministic: report.deterministic,
    }
}

fn upsert_runtime_subagent(state: &WebAppState, session_id: &str, subagent: &WebSubagentEvent) {
    if let Ok(mut sessions) = lock_stream_runtime(state) {
        if let Some(session) = sessions.get_mut(session_id) {
            if let Some(existing) = session
                .subagents
                .iter_mut()
                .find(|item| item.id == subagent.id)
            {
                *existing = subagent.clone();
            } else {
                session.subagents.push(subagent.clone());
            }
        }
    }
}

fn set_runtime_verifier(
    state: &WebAppState,
    session_id: &str,
    report: &WebVerifierReport,
    checkpoints: &[String],
    branch_notes: &[String],
) {
    if let Ok(mut sessions) = lock_stream_runtime(state) {
        if let Some(session) = sessions.get_mut(session_id) {
            session.verifier = Some(report.clone());
            session.checkpoints = checkpoints.to_vec();
            session.branch_notes = branch_notes.to_vec();
        }
    }
}

fn build_research_runtime_event(
    messages: &[MessageBlock],
    session_runtime: Option<&StreamSessionRuntimeView>,
) -> WebResearchRuntimeEvent {
    let mut subagents = Vec::new();
    let mut verifier = None;
    let mut timeline = Vec::new();

    if let Some(runtime) = session_runtime {
        subagents = runtime.subagents.clone();
        verifier = runtime.verifier.clone();
        return WebResearchRuntimeEvent {
            subagents,
            verifier,
            checkpoints: runtime.checkpoints.clone(),
            branch_notes: runtime.branch_notes.clone(),
            timeline: runtime.timeline.clone(),
            resumable: runtime
                .verifier
                .as_ref()
                .is_some_and(|report| report.status.eq_ignore_ascii_case("repair")),
        };
    }

    let start_index = messages
        .iter()
        .rposition(|message| matches!(message, MessageBlock::User { .. }))
        .unwrap_or(0);
    let tail = &messages[start_index..];
    let last_checkpoint_index = tail.iter().rposition(|block| {
        matches!(
            block,
            MessageBlock::Diff { .. } | MessageBlock::Verification { .. }
        )
    });
    let mut checkpoints = Vec::new();
    let mut branch_notes = Vec::new();
    for (index, block) in tail.iter().enumerate() {
        match block {
            MessageBlock::Subagent { record } => subagents.push(to_web_subagent(record)),
            MessageBlock::Verification { report } => verifier = Some(to_web_verifier(report)),
            MessageBlock::ToolCall { name, status, .. } => {
                timeline.push(WebTimelineEvent {
                    kind: "tool_call".to_string(),
                    title: name.clone(),
                    detail: format!("tool status={status:?}"),
                    status: "observed".to_string(),
                    agent: "main".to_string(),
                    ts: String::new(),
                });
            }
            MessageBlock::ToolResult {
                call_id,
                result,
                success,
            } => {
                let tool_name =
                    tool_name_by_call_id(messages, call_id).unwrap_or_else(|| "tool".to_string());
                if !success && !last_checkpoint_index.is_some_and(|checkpoint| checkpoint > index) {
                    branch_notes.push(tail_string(result, 180));
                }
                timeline.push(WebTimelineEvent {
                    kind: "tool_result".to_string(),
                    title: tool_name,
                    detail: if *success {
                        tail_string(result, 120)
                    } else {
                        format!("failed: {}", tail_string(result, 120))
                    },
                    status: if *success {
                        "success".to_string()
                    } else {
                        "failed".to_string()
                    },
                    agent: "main".to_string(),
                    ts: String::new(),
                });
            }
            MessageBlock::Diff { diff } => checkpoints.push(format!(
                "{} (+{} / -{})",
                diff.file_path, diff.added, diff.removed
            )),
            _ => {}
        }
    }
    WebResearchRuntimeEvent {
        resumable: verifier
            .as_ref()
            .is_some_and(|report| report.status.eq_ignore_ascii_case("repair")),
        subagents,
        verifier,
        checkpoints,
        branch_notes,
        timeline,
    }
}

